  "exp.colab.note.wsl": "On WSL install the CLI and run smith inside the distribution; if the OAuth consent does not open the browser, copy the URL into the Windows browser.",
  "exp.colab.registeredHtml": "<span class=\"badge badge--ok\">registered</span> in {files}",
